/**
 * Worker entry (wrangler.jsonc "main"), wrapping the OpenNext handler built into .open-next/
 * (https://opennext.js.org/cloudflare/howtos/custom-worker). Its only job is to add the site
 * security headers to every response, including /_next/image, which OpenNext serves before
 * Next's own header rules run. See src/lib/worker-headers.ts.
 */
import { withWorkerResponseHeaders } from './src/lib/worker-headers'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as openNextHandler } from './.open-next/worker.js'

type FetchHandler = { fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> }

const worker: FetchHandler = {
  async fetch(request, env, ctx) {
    const res = await (openNextHandler as FetchHandler).fetch(request, env, ctx)
    return withWorkerResponseHeaders(res, new URL(request.url).pathname)
  },
}

export default worker

// OpenNext's Durable Object classes, re-exported as its docs require (unused today: no queue,
// tag cache or R2 purge is configured).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'
